"use client";
import { DotLottieReact } from "@lottiefiles/dotlottie-react";
import { useReducedMotion } from "motion/react";

/** Lottie vinyl (public/anim/vinyl.json, generated by scripts/make-lottie.ts). Fills its parent; spins only while composing. */
export function Vinyl({ playing = true, className = "" }: { playing?: boolean; className?: string }) {
  const reduced = useReducedMotion();
  return (
    <div className={`relative aspect-square ${className}`} aria-hidden>
      <DotLottieReact
        src="/anim/vinyl.json"
        loop
        autoplay={playing && !reduced}
        style={{ width: "100%", height: "100%" }}
      />
    </div>
  );
}
